use std::sync::{Arc, RwLock};

#[derive(Default)]
struct OrderRepo { rows: RwLock<Vec<(u64, String)>> }

struct AppState {
    repo: Arc<OrderRepo>,
}

// concept: state extraction hands each handler cheap clones of Arcs
fn find(state: &AppState, id: u64) -> Option<String> {
    state.repo.rows.read().unwrap().iter()
        .find(|(rid, _)| *rid == id)
        .map(|(_, name)| name.clone())
}

fn main() {
    let state = AppState { repo: Arc::new(OrderRepo::default()) };
    println!("{:?}", find(&state, 1));
}

