fn classify(hazard: &str) -> &str {
    match hazard {
        h if h.starts_with("std::fs") => "blocking",
        h if h.contains("Arc<Mutex<DB pool>>") => "fine (short locks)",
        h if h.contains("unbounded") => "unbounded task creation",
        h if h.contains("await") => "deadlock risk",
        _ => "unknown",
    }
}

fn main() {
    for h in [
        "std::fs::read in an async handler",
        "Arc<Mutex<DB pool>>",
        "spawn per request, unbounded",
        "await while holding a lock guard",
    ] {
        println!("{}: {}", h, classify(h));
    }
}
